  "otherTables": "Account management also writes to Login's `identity.audit_events` and to the template's `identity.outbound_events`.",
  "rules": [
    {
      "level": "API level: checked on every request before anything is stored",
      "items": [
        "Managing keys, the password and the account needs a browser session (`auth: session`).",
        "`DELETE /me` needs `confirm: DELETE` and an `Origin` from 01scale.com.",
        "Scopes come from a fixed list; at most 10 active keys; expiry at most 1 year.",
        "`GET /users/{userId}` needs a service token with `identity:users.read`."
      ]
    },
    {
      "level": "Schema level: enforced by the database, whatever the code does",
      "items": [
        "A key belongs to an existing user and is deleted with them.",
        "Each key hash is unique and 64 hex characters.",
        "Every scope is from the allowed list; expiry within a year of creation."
      ]
    },
    {
      "level": "Data model level: business rules the service guarantees",
      "items": [
        "A key works only if not revoked and not expired.",
        "A key's access token never has more than the key's scopes.",
        "Deleting an account deletes the Cognito user first, so a failure leaves everything as it was.",
        "Every service learns of a deletion through the outbox, never by being called in turn."
      ]
    }
  ],
